test("workspace banners and Usage meters account for queued reservations, downgrade overage, and legacy rollout", async ({
  page,
  ownerId,
}, testInfo) => {
  const previous = (
    await pool.query(
      `SELECT "paidGatingEnabled" FROM "SystemControl" WHERE key='global'`,
    )
  ).rows[0].paidGatingEnabled;
  await pool.query(
    `UPDATE "SystemControl" SET "paidGatingEnabled"=true WHERE key='global'`,
  );
  await pool.query(
    `UPDATE "User" SET "gmailAuthorized"=true,"usageBackfillVersion"=1,"usageCutoverAt"=NOW() WHERE id=$1`,
    [ownerId],
  );
  await page.route("**/api/quota", async (route) => {
    const response = await route.fetch();
    const quota = await response.json();
    if (quota.mode === "gated") {
      Object.assign(quota.daily, {
        sent: 5,
        reserved: 2,
        used: 7,
        remaining: 0,
      });
      Object.assign(quota.monthly, {
        sent: 18,
        reserved: 4,
        used: 22,
        remaining: 0,
      });
    } else quota.used = quota.limit;
    await route.fulfill({ response, json: quota });
  });
  async function focusRefresh() {
    await expect(
      page.getByRole("heading", { name: "Usage", exact: true }),
    ).toBeVisible();
    await expect(async () => {
      await Promise.all([
        page.waitForResponse(
          (r) => new URL(r.url()).pathname === "/api/quota",
          { timeout: 1000 },
        ),
        page.evaluate(() => window.dispatchEvent(new Event("focus"))),
      ]);
    }).toPass({ timeout: 15000 });
  }
  try {
    await page.goto("/usage");
    await focusRefresh();
    await expect(
      page
        .getByRole("status", { name: "Daily limit reached" })
        .getByRole("img"),
    ).toHaveAttribute("aria-label", "7 of 3 daily emails used");
    await expect(
      page.getByRole("status").filter({ hasText: "Monthly allowance reached" }),
    ).toContainText("22 of 15 emails used");
    await expect(
      page.getByRole("img", {
        name: "5 sent, 2 queued of 3; 7 used; 0 remaining",
        exact: true,
      }),
    ).toBeVisible();
    await expect(
      page.getByRole("region", { name: "Monthly allowance", exact: true }),
    ).toContainText("7 over the current allowance");
    const getMoreSends = page.getByRole("button", { name: "Get more sends" });
    await expect(getMoreSends).toBeVisible();
    let checkoutRequests = 0;
    await page.route("**/api/billing/checkout", (route) => {
      checkoutRequests++;
      return route.fulfill({ status: 503, json: { error: "Test guard" } });
    });
    const originalUrl = page.url();
    const upgradeDialog = page.getByRole("dialog", {
      name: "Upgrade to Premium",
      exact: true,
    });
    for (const dismissal of ["Escape", "Maybe later"]) {
      await getMoreSends.click();
      await expect(upgradeDialog).toBeVisible();
      await expect(upgradeDialog).toHaveAttribute(
        "data-upgrade-reason",
        "allowance",
      );
      await expect(upgradeDialog).toContainText(
        "Send 20× more and follow up without leaving Mailloop.",
      );
      await expect(page).toHaveURL(originalUrl);
      expect(
        (await new AxeBuilder({ page }).include('[role="dialog"]').analyze())
          .violations,
      ).toEqual([]);
      if (dismissal === "Escape") await page.keyboard.press("Escape");
      else
        await upgradeDialog
          .getByRole("button", { name: "Maybe later" })
          .click();
      await expect(upgradeDialog).toHaveCount(0);
      await expect(getMoreSends).toBeFocused();
    }
    expect(checkoutRequests).toBe(0);
    expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
    expect(
      await page.evaluate(
        () => document.documentElement.scrollWidth <= innerWidth,
      ),
    ).toBe(true);
    const sentSegment = page
      .getByRole("img", {
        name: "5 sent, 2 queued of 3; 7 used; 0 remaining",
        exact: true,
      })
      .locator("span")
      .first();
    const expectedGreen = await sentSegment.evaluate((el) => {
      const swatch = document.createElement("span");
      swatch.style.color = "var(--usage-green)";
      el.appendChild(swatch);
      const color = getComputedStyle(swatch).color;
      swatch.remove();
      return color;
    });
    await expect(sentSegment).toHaveCSS("background-color", expectedGreen);
    await page.screenshot({
      path: testInfo.outputPath("billing-allowances.png"),
      fullPage: true,
    });
    await pool.query(
      `UPDATE "SystemControl" SET "paidGatingEnabled"=false WHERE key='global'`,
    );
    await page.reload();
    await focusRefresh();
    await expect(
      page.getByRole("region", {
        name: "Rolling 24-hour allowance",
        exact: true,
      }),
    ).toBeVisible();
    await expect(
      page.getByText(
        "Capacity returns as sends leave the rolling 24-hour window",
        { exact: false },
      ),
    ).toHaveCount(2);
