test("return avoids overlapping lookups and aborts checking when navigating away", async ({
  page,
  ownerId,
}) => {
  expect(ownerId).toBeTruthy();
  await page.clock.install();
  let reads = 0;
  let release: (() => void) | undefined;
  await page.route("**/api/billing/status", async (route) => {
    reads++;
    await new Promise<void>((resolve) => {
      release = resolve;
    });
    await route.fulfill({ json: { ...status, status: "PENDING" } });
  });
  await page.goto("/usage/return");
  await expect.poll(() => reads).toBe(1);
  await page.clock.fastForward(8000);
  expect(reads).toBe(1);
  release!();
  await expect(
    page.getByRole("region", { name: "Subscription", exact: true }),
  ).toContainText("Subscription: pending");
  await page.goto("/settings");
  await page.clock.fastForward(180_000);
  expect(reads).toBe(1);
});

