test("confirmed return retains cancellation and access notices, with management in Settings", async ({
  page,
  ownerId,
}) => {
  expect(ownerId).toBeTruthy();
  let current = { ...confirmedStatus, hasOverride: true };
  let lookupFails = false;
  await page.route("**/api/billing/status", (route) =>
    route.fulfill(lookupFails ? { status: 503, json: {} } : { json: current }),
  );
  await page.goto("/usage/return");
  const card = page.getByRole("region", { name: "Subscription", exact: true });
  await expect(
    card.getByRole("heading", { name: "You’re on Premium" }),
  ).toBeVisible();
  await expect(card).toContainText("An active access override or grant");
  await expect(
    page.getByRole("link", { name: "Back to Usage", exact: true }),
  ).toHaveCount(1);
  await expect(
    card.getByRole("link", { name: "Back to Usage", exact: true }),
  ).toBeVisible();
  await expect(card.locator("dl > div").first()).toContainText("₹299/month");
  await expect(
    card.getByText("Recurring amount before tax:", { exact: false }),
  ).toContainText("199");
  await expect(card.locator("time").first()).toHaveAttribute(
    "datetime",
    current.periodEnd,
  );
  await expect(
    card.getByRole("button", { name: "Manage subscription", exact: true }),
  ).toHaveCount(0);
  await expect(
    card.getByRole("button", { name: "Cancel at period end", exact: true }),
  ).toHaveCount(0);
  current = { ...current, cancellationPending: true };
  await card
    .getByRole("button", { name: "Refresh status", exact: true })
    .click();
  await expect(card).toContainText(
    "Cancellation requested. Waiting for confirmation; your verified paid period is retained.",
  );
  current = { ...current, cancellationPending: false, cancelAtPeriodEnd: true };
  await card
    .getByRole("button", { name: /^Refresh (?:subscription )?status$/ })
    .click();
  await expect(card).toContainText("Cancellation scheduled.");
  await expect(card).toContainText("Paid period ends");
  await expect(
    card.getByRole("button", { name: "Cancel at period end" }),
  ).toHaveCount(0);
  lookupFails = true;
  await card
    .getByRole("button", { name: /^Refresh (?:subscription )?status$/ })
    .click();
  await expect(
    card.getByRole("alert").filter({ hasText: "lookup temporarily failed" }),
  ).toBeVisible();
  await expect(
    card.getByRole("heading", { name: "You’re on Premium" }),
  ).toBeVisible();
  lookupFails = false;
  current = { ...current, isSuspended: true, plan: "FREE" };
  await card
    .getByRole("button", { name: /^Refresh (?:subscription )?status$/ })
    .click();
  await expect(
    card.getByRole("heading", { name: "Payment confirmed", exact: true }),
  ).toBeVisible();
  await expect(
    card.getByRole("heading", { name: "You’re on Premium" }),
  ).toHaveCount(0);
  await expect(card).toContainText("Access: Suspended");
  await expect(card).toContainText("Suspension does not cancel billing.");
  await expect(
    card.getByRole("button", { name: "Manage subscription", exact: true }),
  ).toHaveCount(0);
  current = {
    ...current,
    isSuspended: false,
    configured: false,
    status: "PAST_DUE",
    gracePeriodEnd: new Date(Date.now() + 86400_000).toISOString(),
  };
  await card
    .getByRole("button", { name: /^Refresh (?:subscription )?status$/ })
    .click();
  await expect(card).toContainText("Access: Free");
  await expect(card).toContainText("The verified grace period ends");
  await expect(card).toContainText("Checkout is not configured yet.");
  await expect(
    card.getByRole("button", { name: "Manage subscription", exact: true }),
  ).toHaveCount(0);
});

